Let's produce final JS only.  import { MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv,
  color,
  texture,
  uniform,
  smoothstep,
  mix,
  length,
  max,
  min,
  abs,
  sub,
  mul,
  add,
  float,
  vec2,
  vec3,
  vec4,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new THREE.Group();
  group.name = config.id || 'hub-pricing-badge';

  const cleanupFns = [];
  const tweens = [];

  // Color tokens from the visualSpec
  const colors = config?.intent?.visualSpec?.colors ?? config?.visual?.colors ?? {};
  const surfaceColor = colors.surface ?? '#0b0b10';
  const accentColor = colors.accent ?? '#ff2a38';

  // Capsule badge sizing
  const sizeX = 1.2;
  const sizeY = 0.75;
  const aspect = sizeX / sizeY;

  const geometry = new THREE.PlaneGeometry(sizeX, sizeY);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: THREE.DoubleSide,
    depthWrite: false,
  });

  const edgeAlpha = uniform(0.0);
  const cornerRadius = 0.22;
  const borderWidth = 0.045;
  const edgeSoft = 0.012;

  material.colorNode = color(surfaceColor);
  material.opacityNode = float(1.0);

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = `${group.name}-mesh`;
  group.add(mesh);

  // Build the shader once the ceramic grain texture is available
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.flipY = false;

    const u = uv();
    const st = sub(u, vec2(0.5));
    const p = vec2(mul(st.x, float(aspect)), st.y);

    const halfB = vec2(mul(0.5, float(aspect)), 0.5);
    const r = float(cornerRadius);
    const bmr = sub(halfB, vec2(r, r));
    const d = sub(length(max(sub(abs(p), bmr), vec2(0.0, 0.0))), r);
    const outerAlpha = smoothstep(float(edgeSoft), float(-edgeSoft), d);

    const halfBin = sub(halfB, vec2(float(borderWidth), float(borderWidth)));
    const rIn = max(sub(r, float(borderWidth)), float(0.0));
    const bmrIn = sub(halfBin, vec2(rIn, rIn));
    const dIn = sub(length(max(sub(abs(p), bmrIn), vec2(0.0, 0.0))), rIn);
    const innerAlpha = smoothstep(float(edgeSoft), float(-edgeSoft), dIn);

    const edgeMask = max(sub(outerAlpha, innerAlpha), float(0.0));

    const map = texture(tex, u);
    const tinted = mix(map.rgb, color(surfaceColor), 0.18);
    const finalRGB = mix(tinted, color(accentColor), mul(edgeMask, edgeAlpha));
    const finalAlpha = mul(map.a, outerAlpha);

    material.colorNode = finalRGB;
    material.opacityNode = finalAlpha;
    material.needsUpdate = true;
  });

  // Cinematic primitives (none expected, but applied if defined)
  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    if (ctx.primitives?.[p.name]) {
      const result = ctx.primitives[p.name](group, p.params ?? {});
      if (result?.cleanup) cleanupFns.push(result.cleanup);
    }
  }

  const setHover = (active) => {
    if (active) {
      if (!group.userData.hovered) {
        group.userData.homeZ = group.position.z;
      }
      group.userData.hovered = true;
      tweens.push(
        gsap.to(group.position, {
          z: (group.userData.homeZ || 0) + 0.15,
          duration: 0.35,
          ease: 'power2.out',
        })
      );
      edgeAlpha.value = 1.0;
    } else {
      group.userData.hovered = false;
      tweens.push(
        gsap.to(group.position, {
          z: group.userData.homeZ || 0,
          duration: 0.35,
          ease: 'power2.out',
        })
      );
      edgeAlpha.value = 0.0;
    }
  };

  const pressDown = () => {
    tweens.push(
      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
      })
    );
  };

  const pressUp = () => {
    tweens.push(
      gsap.to(group.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.15,
        ease: 'power2.out',
      })
    );
  };

  group.userData.handlers = {
    pointerenter: () => setHover(true),
    pointerleave: () => setHover(false),
    mouseenter: () => setHover(true),
    mouseleave: () => setHover(false),
    pointerdown: pressDown,
    pointerup: pressUp,
    focus: () => {
      edgeAlpha.value = 1.0;
    },
    blur: () => {
      edgeAlpha.value = 0.0;
    },
    click: () => {
      ctx.emit('hub-pricing.select', { nodeId: config.id });
    },
  };

  group.userData.cleanup = () => {
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);

    for (const t of tweens) {
      t?.kill();
    }

    for (const fn of cleanupFns) {
      fn?.();
    }

    geometry.dispose();
    material.dispose();
  };

  return group;
}
